import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  const group = new Group();
  group.position.set(3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Atlas region: 0, 0, 512, 320 from a likely 1024x1024 atlas
  // Aspect ratio: 512/320 = 1.6
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspectRatio = atlasWidth / atlasHeight;

  // Create a plane geometry with the correct aspect ratio
  // Height = 1.2 units (reasonable card size), width scales by aspect ratio
  const height = 1.2;
  const width = height * aspectRatio;
  const geometry = new PlaneGeometry(width, height);

  // Load the ceramic-grain texture
  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  texturePromise.then((texture) => {
    if (!texture) return;

    // Set up texture for atlas region
    // Assuming 1024x1024 atlas; UV region is [0, 0, 512, 320]
    const atlasSize = 1024;
    const offsetX = 0 / atlasSize;
    const offsetY = 0 / atlasSize;
    const scaleX = atlasWidth / atlasSize;
    const scaleY = atlasHeight / atlasSize;

    texture.offset.set(offsetX, offsetY);
    texture.repeat.set(scaleX, scaleY);
    texture.needsUpdate = true;

    // Create material with TSL nodes
    const mapNode = texture ? uv().mul(vec4(scaleX, scaleY, 1, 1)).add(vec4(offsetX, offsetY, 0, 0)) : uv();

    const material = new MeshBasicNodeMaterial({
      colorNode: texture ? texture : undefined,
      map: texture,
      transparent: true,
      depthTest: true,
      depthWrite: true,
    });

    const mesh = new Mesh(geometry, material);
    group.add(mesh);

    // Store cleanup
    group.userData.cleanup = () => {
      if (texture) texture.dispose();
      geometry.dispose();
      material.dispose();
      mesh.removeFromParent();
    };
  });

  // Fallback cleanup if no texture loads
  if (!group.userData.cleanup) {
    group.userData.cleanup = () => {
      geometry.dispose();
    };
  }

  return group;
}
